CREATE TABLE IF NOT EXISTS "Guests" (
	"guest_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"guest_name" VARCHAR(255) NOT NULL,
	"g_phone" VARCHAR(15) NOT NULL CONSTRAINT chk_phone CHECK (g_phone ~ '^\+[1-9]\d{1,13}$'),
	"g_document_number" VARCHAR(50),
	"g_document_type" VARCHAR(50) CONSTRAINT chk_doc_type CHECK (g_document_type IN ('id', 'passport', 'driver license')),
	"g_email" VARCHAR(255),
	"g_created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY("guest_id"),
	CONSTRAINT "Guests_unique_0" UNIQUE ("g_document_number", "g_document_type")
);

CREATE TABLE IF NOT EXISTS "Rooms" (
	"room_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"room_number" INTEGER NOT NULL,
	"hotel_id" INTEGER NOT NULL,
	"r_basic_capacity" INTEGER NOT NULL CHECK ("capacity" >= 1),
	"r_additional_capacity" INTEGER NOT NULL DEFAULT 0,
	"r_bed_type" VARCHAR(50) NOT NULL CHECK(CONSTRAINT chk_bed_type CHECK (r_bed_type IN ('single', 'double', 'both')),
	"r_view" BOOLEAN NOT NULL,
	"r_jacuzzi" BOOLEAN NOT NULL,
	PRIMARY KEY("room_id"),
	CONSTRAINT "Rooms_unique_0" UNIQUE ("hotel_id", "room_number")
);

CREATE TABLE IF NOT EXISTS "Room_pricing_changes" (
	"room_id" INTEGER NOT NULL,
	"r_price_valid_from" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	-- current price's date_till is 01/01/2099
	"r_price_valid_till" TIMESTAMPTZ NOT NULL DEFAULT TO_TIMESTAMP('01-01-2099', 'DD-MM-YYYY'),
	"r_basic_price" NUMERIC(10,2) NOT NULL,
	"r_additional_guest_price" NUMERIC(10,2) NOT NULL DEFAULT 0,
	"r_high_season_rate" NUMERIC(3,2) NOT NULL DEFAULT 1,
	"r_weekend_rate" NUMERIC(3,2) NOT NULL DEFAULT 1,
	PRIMARY KEY("room_id", "r_price_valid_from"),
	CONSTRAINT "Room_pricing_changes_unique_0" UNIQUE ("room_id", "r_price_valid_till"),
	CONSTRAINT chk_r_price_date CHECK (r_price_valid_till > r_price_valid_from)
);

COMMENT ON COLUMN "Room_pricing_changes"."r_price_valid_till" IS 'current price''s date_till is 01/01/2099';

CREATE TABLE IF NOT EXISTS "Bookings" (
	"booking_id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"b_created_at" TIMESTAMPTZ NOT NULL,
	-- this fields has impact on view that shows rooms availability
	"b_stay_from" TIMESTAMPTZ NOT NULL,
	-- this fields has impact on view that shows rooms availability
	"b_stay_till" TIMESTAMPTZ NOT NULL,
	"guest_id" INTEGER NOT NULL,
	"is_prepaid" BOOLEAN NOT NULL,
	"b_handled_by" INTEGER NOT NULL,
	PRIMARY KEY("booking_id"),
	CONSTRAINT chk_stay_date CHECK (b_stay_till > b_stay_from)
);

COMMENT ON COLUMN "Bookings"."b_stay_from" IS 'this fields has impact on view that shows rooms availability';
COMMENT ON COLUMN "Bookings"."b_stay_till" IS 'this fields has impact on view that shows rooms availability';

CREATE TABLE IF NOT EXISTS "Booking_details" (
	"booking_id" BIGINT NOT NULL,
	-- this fields has impact on view that shows rooms availability
	"room_id" INTEGER NOT NULL,
	"with_breakfast" BOOLEAN NOT NULL,
	"guests_number" INTEGER,
	PRIMARY KEY("booking_id", "room_id")
);

COMMENT ON COLUMN "Booking_details"."room_id" IS 'this fields has impact on view that shows rooms availability';

CREATE TABLE IF NOT EXISTS "Booking_status" (
	"booking_status" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"booking_status_name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("booking_status")
);

CREATE TABLE IF NOT EXISTS "Booking_status_history" (
	"booking_id" BIGINT NOT NULL,
	"changed_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	"booking_status" INTEGER NOT NULL,
	PRIMARY KEY("booking_id", "changed_at")
);

CREATE TABLE IF NOT EXISTS "Booking_services" (
	"booking_id" BIGINT NOT NULL,
	"service_id" INTEGER NOT NULL,
	"s_handled_by" INTEGER
	"quantity" INTEGER CHECK ("quantity" > 0),
	PRIMARY KEY("booking_id", "service_id")
);

CREATE TABLE IF NOT EXISTS "Customer_invoices" (
	"invoice_id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"inv_sum" NUMERIC(10,2) NOT NULL,
	"discount" NUMERIC(3,2) NOT NULL DEFAULT 0,
	"booking_id" BIGINT UNIQUE,
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("invoice_id")
);

CREATE TABLE IF NOT EXISTS "Customer_payments" (
	"receipt_id" BIGINT NOT NULL,
	"payment_at" TIMESTAMPTZ NOT NULL,
	"invoice_id" BIGINT NOT NULL,
	"payment_method" VARCHAR(50) NOT NULL CHECK(CONSTRAINT chk_pay_method CHECK (payment_method IN ('card', 'cash', 'other')),
	"payment_sum" NUMERIC(10,2) NOT NULL,
	"payment_status" INTEGER NOT NULL,
	PRIMARY KEY("receipt_id"),
	CONSTRAINT "Customer_payments_unique_0" UNIQUE ("payment_at", "invoice_id")
);

CREATE TABLE IF NOT EXISTS "Payment_statuses" (
	"payment_status" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"pay_status_name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("payment_status")
);

CREATE TABLE IF NOT EXISTS "Services" (
	"service_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"service_name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("service_id")
);

CREATE TABLE IF NOT EXISTS "Additional_services_pricing" (
	"service_id" INTEGER NOT NULL,
	"s_price_valid_from" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	-- current price date_till is 01/01/2099
	"s_price_valid_till" TIMESTAMPTZ NOT NULL DEFAULT TO_TIMESTAMP('01-01-2099', 'DD-MM-YYYY'),
	"s_price" NUMERIC(10,2) NOT NULL,
	PRIMARY KEY("service_id", "s_price_valid_from"),
	CONSTRAINT "Additional_services_pricing_unique_0" UNIQUE ("service_id", "s_price_valid_till"),
	CONSTRAINT chk_s_price_date CHECK (s_price_valid_till > s_price_valid_from)
);

COMMENT ON COLUMN "Additional_services_pricing"."s_price_valid_till" IS 'current price date_till is 01/01/2099';

CREATE TABLE IF NOT EXISTS "Actual_stays" (
	"stay_id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"room_id" INTEGER NOT NULL,
	"booking_id" BIGINT NOT NULL,
	"check_in" TIMESTAMPTZ NOT NULL,
	"check_out" TIMESTAMPTZ,
	PRIMARY KEY("stay_id"),
	CONSTRAINT chk_in_out_date CHECK (check_out IS NULL OR check_out > check_in)
);
-- one open stay per room
CREATE UNIQUE INDEX uq_one_open_stay_per_room
  ON actual_stays (room_id) WHERE check_out IS NULL;


CREATE TABLE IF NOT EXISTS "Hotels" (
	"hotel_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"hotel_name" VARCHAR(100) NOT NULL,
	"hotel_adress" VARCHAR(255) NOT NULL,
	PRIMARY KEY("hotel_id")
);

CREATE TABLE IF NOT EXISTS "Employees" (
	"employee_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"employee_name" VARCHAR(255) NOT NULL,
	"hotel_id" INTEGER NOT NULL,
	"manager_id" INTEGER,
	PRIMARY KEY("employee_id")
);

